// Terminology freeze (U15 microcopy standard). Use exactly one name per
// concept across ALL locales and components , do not reintroduce synonyms:
//   Hermes server = the local on-device service the app talks to. "Hermes"
//              alone is fine in short rows. Infrastructure words (gateway,
//              daemon, vault, proot, telemetry) never reach user copy.
//   Provider = an LLM endpoint profile (DeepSeek, OpenAI, ...). Never
//              "Profile" in user copy; "profile" survives only as the
//              settings-storage field name (profileLabel = Profile Name).
//   Task     = a scheduled background job: EN "scheduled task", AR "مهمة
//              مجدولة". Never bare "Job" or the word "Cron" in user copy.
//   Session  = one workspace conversation. Forking = "Fork Session" /
//              "استنساخ الجلسة". Never "branch"/"dump"/"تفريغ".
//   Assistant= the agent persona. AR "المساعد". Never "الوكيل" (that word
//              is reserved for a network proxy: customProxy = "وكيل مخصص").
//   Routine  = a prebuilt automation pattern: EN "Routine templates",
//              AR "قوالب الروتين". "Blueprint" is retired from user copy.
// Brand/Latin tokens inside RTL strings MUST be wrapped in U+2068..U+2069
// isolates so "(DeepSeek وOpenAI)"-style runs render in the right order.
export interface LanguageItem {
  id: string;
  name: string;
  code: string;
  dir?: 'ltr' | 'rtl';
}

export const LANGUAGES: LanguageItem[] = [
  { id: 'en', name: 'English', code: 'EN', dir: 'ltr' },
  { id: 'ar', name: 'العربية', code: 'AR', dir: 'rtl' },
  { id: 'zh', name: '简体中文', code: 'ZH', dir: 'ltr' },
  { id: 'ja', name: '日本語', code: 'JA', dir: 'ltr' },
  { id: 'ru', name: 'Русский', code: 'RU', dir: 'ltr' },
  { id: 'fr', name: 'Français', code: 'FR', dir: 'ltr' },
  { id: 'de', name: 'Deutsch', code: 'DE', dir: 'ltr' },
  { id: 'es', name: 'Español', code: 'ES', dir: 'ltr' },
];

export type LanguageCode = 'en' | 'ar' | 'zh' | 'ja' | 'ru' | 'fr' | 'de' | 'es';

